  'album.unlockedByYou': 'You unlocked your private album for them',
  'discover.noLocation.later': 'You can update your location any time with the 📍 button next to Filters.',
  'court.howTitle': 'How courting works',
  'court.how.what': 'Courting is paying coins to raise someone standing. Your name shows on their profile as the person courting them, and their court value goes up by what you paid.',
  'court.how.cost': 'Each court costs double their current value, so the price rises every time. Half of what you pay goes to them as coins they can spend; the other half leaves circulation.',
  'court.how.expiry': 'A court lasts 30 days from the last time anyone paid. If nobody courts them again in that window, their court value drops back to 2 and the title disappears.',
  'court.how.rank': 'Court value is the top leaderboard, and it is the only board money moves directly. Staying at the top means being courted again before the 30 days run out.',
  'court.thenZero': 'then it drops back to 2',
  'court.lapsed': 'Your court value is running out. Being courted again resets it to 30 days.',
  'settings.faq': 'How RIDE works',
  'faq.intro': 'Everything here in plain terms — what each thing does, and what actually changes it.',
  'faq.what.q': 'What is RIDE?',
  'faq.what.a': 'A social app that runs inside Telegram. You get a profile, a feed, stories and private chat, plus a set of ways to show interest in people: woofs, gifts and courting. Discover finds people near you or anywhere in the world, and the leaderboards rank who is getting the most attention right now.',
  'faq.username.q': 'Username vs display name?',
  'faq.username.a': 'Your username is how you are addressed everywhere — in comments, chats, alerts and the leaderboards — and it is unique to you. Your display name is what you are called, shown on your profile and on Discover tiles. Neither is your Telegram username, and changing either does not change your Telegram account.',
  'faq.woof.q': 'What is a woof?',
  'faq.woof.a': 'A free nudge you send from someone profile, saying you noticed them. One per person per cooldown, so the woofs board measures how many different people came by rather than how often one person tapped.',
  'faq.court.q': 'What is courting and court value?',
  'faq.court.a': 'Courting is paying coins to raise someone standing. Their court value goes up, your name appears on their profile as the person courting them, and they sit higher on the court board. It lasts 30 days from the last court. If nobody courts them again in that window their court value drops back to 2 — the starting value — and the title disappears. It is a standing you have to keep, not something you buy once.',
  'faq.courtMoney.q': 'What does courting cost, and who gets the money?',
  'faq.courtMoney.a': 'Each court costs double the person current value, so the price rises every time. Half of what you pay goes straight to the person you courted as coins they can spend. The other half leaves circulation.',
  'faq.coins.q': 'What are coins for?',
  'faq.coins.a': 'Coins pay for gifts and for courting. You get them by being courted, from your daily login streak, and by buying them with Telegram Stars. Coins are not money and cannot be cashed out.',
  'faq.gifts.q': 'What are gifts?',
  'faq.gifts.a': 'Small items you buy with coins and send to someone. They appear in the gifts tab on their profile. The gifts board counts how many gifts a person received, not what they cost — ten cheap gifts from ten people outrank one expensive gift from one.',
  'faq.ranks.q': 'How do the leaderboards work?',
  'faq.ranks.a': 'Five boards: court value, woofs, likes, gifts and followers. Woofs, likes, gifts and followers can be filtered by today, this week, this month or all time, and each one counts only what happened inside that window — so the daily boards reset every day. Court value has no periods, because it is a live standing that expires rather than a tally of events.',
  'faq.discover.q': 'Grid and Global?',
  'faq.discover.a': 'Grid shows people near you and needs your location to work. Global ignores location entirely and shows everyone, with people who are online or recently active first. Filters apply to both.',
  'faq.location.q': 'How does location work?',
  'faq.location.a': 'You share it from the bot chat, and it is snapped to a grid of roughly 500 metres before it is stored — so nobody can be pinpointed. Distances always show as ranges, never exact. Update it any time with the location button next to Filters in Discover.',
  'faq.private.q': 'What is the private album?',
  'faq.private.a': 'A locked set of photos on your profile. Nobody sees them until you unlock them for that person in your private chat, and you can lock it again at any point, which takes the access away. Posting with visibility set to Private also puts the photos there.',
  'faq.stories.q': 'How do stories work?',
  'faq.stories.a': 'They last 24 hours. Tap the right side to move forward, the left side to go back — nothing advances on its own. You can see who watched yours, and a reply to a story arrives in your private chat marked as a reply to it.',
  'faq.verify.q': 'What does the blue check mean?',
  'faq.verify.a': 'That the person sent a photo matching a pose we asked for, and a human approved it. It means the account is a real person, not that it is important.',
  'faq.ghost.q': 'What is ghost mode?',
  'faq.ghost.a': 'It hides you from Discover so people cannot browse to you. Your posts, your profile and your leaderboard positions are unaffected — anyone with your profile open can still see it.',
  'faq.block.q': 'What happens when I block someone?',
  'faq.block.a': 'They cannot message you, see your posts, stories or profile, and your conversation disappears for both of you. They are not told. They still appear on the leaderboards, because a rank is earned and blocking is not a way to remove someone from it. They appear in Settings under Blocked users, and you can unblock them there or from their profile.',
  'faq.report.q': 'What happens when I report something?',
  'faq.report.a': 'It goes to the moderators with what you wrote. They can delete the post or ban the account. You will not be told the outcome, but action is taken when it is warranted.',
  'faq.delete.q': 'What happens if I delete my account?',
  'faq.delete.a': 'Everything goes: profile, photos, posts, comments, messages, coins and gifts are removed from the database permanently. It cannot be undone and nothing is kept in the background.',
