  'court.howTitle': 'Kur nasıl işler',
  'court.how.what': 'Kur, birinin itibarını yükseltmek için coin harcamaktır. Adın onun profilinde kur yapan kişi olarak görünür ve court değeri ödediğin kadar artar.',
  'court.how.cost': 'Her kur, kişinin mevcut değerinin iki katına mal olur; yani fiyat her seferinde artar. Ödediğinin yarısı harcayabileceği coin olarak ona gider, diğer yarısı dolaşımdan çıkar.',
  'court.how.expiry': 'Bir kur, son ödemeden itibaren 30 gün sürer. Bu sürede kimse tekrar kur yapmazsa court değeri 2’ye düşer ve unvan kaybolur.',
  'court.how.rank': 'Court değeri en üstteki sıralamadır ve paranın doğrudan etkilediği tek tablodur. Zirvede kalmak, 30 gün dolmadan yeniden kur yapılması demektir.',
  'court.thenZero': 'sonra 2’ye düşer',
  'court.lapsed': 'Court değerin tükeniyor. Yeniden kur yapılması süreyi 30 güne sıfırlar.',
  'settings.faq': 'RIDE nasıl çalışır',
  'faq.intro': 'Her şey sade bir dille: ne işe yarıyor ve neyi gerçekten değiştiriyor.',
  'faq.what.q': 'RIDE nedir?',
  'faq.what.a': 'Telegram içinde çalışan bir sosyal uygulama. Profil, akış, hikâyeler ve özel sohbetin olur; ayrıca ilgini göstermenin yolları: woof, hediye ve kur. Keşfet yakınındaki ya da dünyanın her yerindeki insanları bulur, sıralamalar ise şu an en çok ilgi görenleri gösterir.',
  'faq.username.q': 'Kullanıcı adı ile görünen ad farkı?',
  'faq.username.a': 'Kullanıcı adın her yerde — yorumlarda, sohbetlerde, bildirimlerde ve sıralamalarda — sana hitap etme biçimidir ve sana özeldir. Görünen ad ise profilinde ve Keşfet kartlarında yazan addır. Hiçbiri Telegram kullanıcı adın değildir.',
  'faq.woof.q': 'Woof nedir?',
  'faq.woof.a': 'Birinin profilinden gönderdiğin ücretsiz bir dürtme; fark ettiğini söyler. Kişi başına bir tane, yani bu tablo kaç farklı kişinin uğradığını ölçer.',
  'faq.court.q': 'Kur ve court değeri nedir?',
  'faq.court.a': 'Kur, birinin itibarını yükseltmek için coin ödemektir. Court değeri artar, adın profilinde kur yapan kişi olarak görünür ve court tablosunda yükselir. Son kurdan itibaren 30 gün sürer. Bu sürede kimse tekrar kur yapmazsa değer başlangıç değeri olan 2’ye düşer ve unvan kaybolur. Bir kez satın alınan değil, korunması gereken bir itibardır.',
  'faq.courtMoney.q': 'Kur ne kadar tutar ve para kime gider?',
  'faq.courtMoney.a': 'Her kur, kişinin mevcut değerinin iki katıdır; fiyat her seferinde yükselir. Ödediğinin yarısı doğrudan ona harcayabileceği coin olarak geçer. Diğer yarısı dolaşımdan çıkar.',
  'faq.coins.q': 'Coin ne işe yarar?',
  'faq.coins.a': 'Coin, hediye ve kur için kullanılır. Kur yapıldığında, günlük giriş serinden ve Telegram Stars ile satın alarak kazanırsın. Coin para değildir ve nakde çevrilemez.',
  'faq.gifts.q': 'Hediyeler nedir?',
  'faq.gifts.a': 'Coin ile alıp birine gönderdiğin küçük öğeler. Profilindeki hediyeler sekmesinde görünür. Hediye tablosu fiyata göre değil adede göre sayar: on kişiden gelen ucuz hediye, tek kişiden gelen pahalı hediyeyi geçer.',
  'faq.ranks.q': 'Sıralamalar nasıl işler?',
  'faq.ranks.a': 'Beş tablo: court değeri, woof, beğeni, hediye ve takipçi. Woof, beğeni, hediye ve takipçi bugün, bu hafta, bu ay veya tüm zamanlar olarak filtrelenir ve yalnızca o aralıkta olanları sayar; yani günlük tablolar her gün sıfırlanır. Court değerinin dönemi yoktur, çünkü o bir olay sayımı değil, süresi dolan canlı bir itibardır.',
  'faq.discover.q': 'Izgara ve Küresel?',
  'faq.discover.a': 'Izgara yakınındaki kişileri gösterir ve konumun gerekir. Küresel konumu tamamen yok sayar ve herkesi gösterir; çevrimiçi olanlar ve son zamanlarda aktif olanlar önce gelir. Filtreler ikisinde de geçerlidir.',
  'faq.location.q': 'Konum nasıl çalışır?',
  'faq.location.a': 'Konumu bot sohbetinden paylaşırsın ve kaydedilmeden önce yaklaşık 500 metrelik bir ızgaraya oturtulur; yani kimse tam olarak bulunamaz. Mesafeler her zaman aralık olarak gösterilir, asla kesin değil. Keşfet’te Filtreler yanındaki konum düğmesiyle istediğin zaman güncelleyebilirsin.',
  'faq.private.q': 'Özel albüm nedir?',
  'faq.private.a': 'Profilindeki kilitli fotoğraf grubu. Özel sohbette o kişiye açana kadar kimse göremez ve istediğin an tekrar kilitleyebilirsin, bu erişimi geri alır. Gizlilik olarak “Özel” seçilerek paylaşılan gönderilerin fotoğrafları da oraya gider.',
  'faq.stories.q': 'Hikâyeler nasıl çalışır?',
  'faq.stories.a': '24 saat sürer. İleri gitmek için sağa, geri gitmek için sola dokun; hiçbir şey kendiliğinden ilerlemez. Hikâyeni kimin izlediğini görebilirsin ve bir hikâyeye gelen yanıt, hikâye yanıtı olarak işaretlenmiş şekilde özel sohbetine düşer.',
  'faq.verify.q': 'Mavi tik ne anlama gelir?',
  'faq.verify.a': 'Kişinin istediğimiz poza uyan bir fotoğraf gönderdiği ve bir insanın bunu onayladığı anlamına gelir. Hesabın gerçek bir kişiye ait olduğunu gösterir, önemli olduğunu değil.',
  'faq.ghost.q': 'Hayalet mod nedir?',
  'faq.ghost.a': 'Seni Keşfet’ten gizler, böylece kimse gezinerek sana ulaşamaz. Gönderilerin, profilin ve sıralama konumların etkilenmez — profilini açmış olan biri hâlâ görebilir.',
  'faq.block.q': 'Birini engellersem ne olur?',
  'faq.block.a': 'Sana mesaj atamaz; gönderilerini, hikâyelerini ve profilini göremez ve sohbetiniz iki taraf için de kaybolur. Kendisine bildirilmez. Sıralamalarda görünmeye devam eder, çünkü sıra kazanılmış bir şeydir ve engelleme birini oradan çıkarmanın yolu değildir. Ayarlar’daki Engellenen kullanıcılar listesinde görünür; oradan ya da profilinden engeli kaldırabilirsin.',
  'faq.report.q': 'Bir şeyi şikâyet edersem ne olur?',
  'faq.report.a': 'Yazdıklarınla birlikte moderatörlere gider. Gönderiyi silebilir veya hesabı yasaklayabilirler. Sonuç sana bildirilmez, ama gerektiğinde işlem yapılır.',
  'faq.delete.q': 'Hesabımı silersem ne olur?',
  'faq.delete.a': 'Her şey gider: profil, fotoğraflar, gönderiler, yorumlar, mesajlar, coinler ve hediyeler veritabanından kalıcı olarak silinir. Geri alınamaz ve arka planda hiçbir şey saklanmaz.',
  'support.hint': 'Ne olduğunu yaz. Bir yönetici bunu kullanıcı adınla birlikte alır ve yanıtlar bot sohbetinden gelir.',
  'support.placeholder': 'Ne oldu?',
  'support.send': 'Gönder',
  'support.sentTitle': 'Mesaj gönderildi',
  'support.sentBody': 'Bir yöneticiye kullanıcı adınla birlikte ulaştı. Yanıtlar bot sohbetinden gelir.',
  'discover.noLocation': 'Yakındakileri görmek için konumunu paylaş',
  'discover.noLocation.body': 'Izgara mesafeye göre sıralanır, bu yüzden bir kez konum paylaşana kadar boş kalır. Filtreler yanındaki 📍 düğmesiyle istediğin zaman güncelleyebilir veya kaldırabilirsin.',
  'discover.shareLocation': 'Konumumu paylaş',
