  'ranks.how.court': 'Court değeri itibarındır. Biri sana kur yapmak için coin harcadığında yükselir ve paranın doğrudan etkilediği tek tablodur. Bir kur, son ödemeden itibaren 30 gün sürer — bu sürede kimse tekrar kur yapmazsa değerin 2’ye düşer ve bu tablodan çıkarsın; yani zirvede kalmak süre dolmadan yeniden kur yapılması demektir.',
