  'ranks.howTitle': 'Как работает эта таблица',
  'ranks.how.court': 'Court value — ваш статус. Он растёт, когда кто-то тратит монеты, чтобы за вами поухаживать, и это единственная таблица, на которую деньги влияют напрямую. Ухаживание действует 30 дней с последней оплаты: если никто не поухаживает снова, значение падает до 2 и вы выбываете из таблицы.',
