  'faq.intro': 'كل شيء بكلمات واضحة: ماذا يفعل كل عنصر وما الذي يغيّر النتيجة فعلًا.',
  'faq.what.q': 'ما هو RIDE؟',
  'faq.what.a': 'تطبيق اجتماعي يعمل داخل تيليجرام. لديك ملف شخصي وموجز وقصص ومحادثات خاصة، إضافة إلى طرق لإظهار الاهتمام: الووف والهدايا والتودد. يعثر «اكتشف» على أشخاص قريبين منك أو في أي مكان في العالم، وتُظهر الجداول من يحظى بأكبر اهتمام الآن.',
  'faq.username.q': 'اسم المستخدم أم الاسم الظاهر؟',
  'faq.username.a': 'اسم المستخدم هو الطريقة التي تُنادى بها في كل مكان — في التعليقات والمحادثات والتنبيهات والجداول — وهو خاص بك وحدك. أما الاسم الظاهر فهو ما تُسمّى به، ويظهر في ملفك وفي بطاقات «اكتشف». ولا أحد منهما هو اسم مستخدمك في تيليجرام.',
  'faq.woof.q': 'ما هو الووف؟',
  'faq.woof.a': 'لفتة مجانية ترسلها من ملف شخص لتقول إنك لاحظته. واحدة لكل شخص، لذا يقيس الجدول عدد الأشخاص المختلفين الذين مرّوا، لا عدد مرات عودة شخص واحد.',
  'faq.court.q': 'ما التودد وقيمة التودد؟',
  'faq.court.a': 'التودد هو دفع عملات لرفع مكانة شخص ما. ترتفع قيمة تودده، ويظهر اسمك في ملفه، ويصعد في الجدول. يستمر ٣٠ يومًا من آخر تودد. وإذا لم يتودد إليه أحد مجددًا خلال هذه المدة تعود القيمة إلى ٢ — قيمة البداية — ويختفي اللقب. إنها مكانة تحتاج إلى المحافظة عليها، لا شيء يُشترى مرة واحدة.',
  'faq.courtMoney.q': 'كم يكلّف التودد ومن يأخذ المال؟',
  'faq.courtMoney.a': 'كل تودد يكلّف ضعف القيمة الحالية للشخص، لذا يرتفع السعر. نصف ما تدفعه يذهب إليه مباشرة عملاتٍ يمكنه إنفاقها. والنصف الآخر يخرج من التداول.',
  'faq.coins.q': 'ما فائدة العملات؟',
  'faq.coins.a': 'تُستخدم العملات للهدايا وللتودد. تحصل عليها عندما يُتودد إليك، ومن سلسلة الدخول اليومية، وبشرائها عبر Telegram Stars. العملات ليست نقودًا ولا يمكن سحبها.',
  'faq.gifts.q': 'ما الهدايا؟',
  'faq.gifts.a': 'أشياء صغيرة تشتريها بالعملات وترسلها لشخص ما. تظهر في تبويب الهدايا في ملفه. يحسب الجدول عدد الهدايا لا ثمنها: عشر هدايا رخيصة من عشرة أشخاص تتفوق على هدية غالية من شخص واحد.',
  'faq.ranks.q': 'كيف تعمل الجداول؟',
  'faq.ranks.a': 'خمسة جداول: قيمة التودد، والووف، والإعجابات، والهدايا، والمتابعين. يمكن تصفية الووف والإعجابات والهدايا والمتابعين حسب اليوم أو الأسبوع أو الشهر أو كل الأوقات، وتحسب فقط ما حدث داخل تلك المدة، لذا تُصفَّر الجداول اليومية كل يوم. أما قيمة التودد فلا فترات لها، لأنها ليست عدّ أحداث بل مكانة حيّة تنتهي صلاحيتها.',
  'faq.discover.q': 'الشبكة والعالمي؟',
  'faq.discover.a': 'تعرض الشبكة أشخاصًا قريبين منك وتحتاج إلى موقعك. أما العالمي فيتجاهل الموقع تمامًا ويعرض الجميع، والمتصلون أو النشطون مؤخرًا في المقدمة. وتنطبق الفلاتر على الاثنين.',
  'faq.location.q': 'كيف يعمل الموقع؟',
  'faq.location.a': 'تشاركه من محادثة البوت، ويُثبَّت على شبكة بحدود ٥٠٠ متر قبل حفظه، لذا لا يمكن تحديد أحد بدقة. وتظهر المسافات دائمًا كنطاقات لا كأرقام دقيقة. حدّثه متى شئت من زر الموقع بجانب الفلاتر.',
  'faq.private.q': 'ما الألبوم الخاص؟',
