  'album.unlockedNotice': 'şəxsi albomunu sənin üçün açdı',
  'album.unlockedByYou': 'Şəxsi albomunu onun üçün açdın',
  'discover.noLocation.later': 'Məkanını istənilən vaxt Filtrlərin yanındakı 📍 düyməsi ilə yeniləyə bilərsən.',
  'court.howTitle': 'Dərgah necə işləyir',
  'court.how.what': 'Dərgah birinin nüfuzunu qaldırmaq üçün coin xərcləməkdir. Adın onun profilində dərgah quran şəxs kimi görünür və dərgah dəyəri ödədiyin qədər artır.',
  'court.how.cost': 'Hər dərgah şəxsin cari dəyərinin iki qatına başa gəlir, yəni qiymət hər dəfə qalxır. Ödədiyinin yarısı ona xərcləyə biləcəyi coin kimi keçir, digər yarısı dövriyyədən çıxır.',
  'court.how.expiry': 'Dərgah son ödənişdən 30 gün davam edir. Bu müddətdə kimsə yenidən dərgah qurmasa, dəyər 2-yə düşür və ad itir.',
  'court.how.rank': 'Dərgah dəyəri ən üst cədvəldir və pulun birbaşa təsir etdiyi yeganə cədvəldir. Zirvədə qalmaq 30 gün bitmədən yenidən dərgah qurulması deməkdir.',
  'court.thenZero': 'sonra 2-yə düşür',
  'court.lapsed': 'Dərgah dəyərin bitmək üzrədir. Yenidən dərgah qurulması müddəti 30 günə sıfırlayır.',
  'settings.faq': 'RIDE necə işləyir',
  'faq.intro': 'Hər şey sadə dillə: nə edir və nəyi həqiqətən dəyişir.',
  'faq.what.q': 'RIDE nədir?',
  'faq.what.a': 'Telegram daxilində işləyən sosial tətbiq. Profil, lent, hekayələr və şəxsi söhbət, üstəlik maraq göstərmək üçün yollar: ووf, hədiyyə və dərgah. Kəşf yaxınlıqdakı və ya dünyanın hər yerindəki insanları tapır, cədvəllər isə hazırda ən çox diqqət çəkənləri göstərir.',
  'faq.username.q': 'İstifadəçi adı ilə görünən ad arasında fərq?',
  'faq.username.a': 'İstifadəçi adın hər yerdə — şərhlərdə, söhbətlərdə, bildirişlərdə və cədvəllərdə — sənə müraciət formasıdır və yalnız sənindir. Görünən ad profilində və Kəşf kartlarında yazılan addır. Heç biri Telegram istifadəçi adın deyil.',
  'faq.woof.q': 'Woof nədir?',
  'faq.woof.a': 'Birinin profilindən göndərdiyin pulsuz toxunuş; fərq etdiyini bildirir. Hər şəxsə bir dəfə, yəni bu cədvəl neçə fərqli adamın gəldiyini ölçür.',
  'faq.court.q': 'Dərgah və dərgah dəyəri nədir?',
  'faq.court.a': 'Dərgah birinin nüfuzunu qaldırmaq üçün coin ödəməkdir. Dərgah dəyəri artır, adın onun profilində görünür və cədvəldə yüksəlir. Son dərgahdan 30 gün davam edir. Bu müddətdə kimsə yenidən dərgah qurmasa, dəyər başlanğıc dəyəri olan 2-yə düşür və ad itir. Bir dəfə alınan yox, saxlanılması lazım olan nüfuzdur.',
  'faq.courtMoney.q': 'Dərgah nə qədərdir və pul kimə gedir?',
  'faq.courtMoney.a': 'Hər dərgah şəxsin cari dəyərinin iki qatıdır, qiymət hər dəfə qalxır. Ödədiyinin yarısı birbaşa ona xərcləyə biləcəyi coin kimi keçir. Digər yarısı dövriyyədən çıxır.',
  'faq.coins.q': 'Coin nə üçündür?',
  'faq.coins.a': 'Coin hədiyyə və dərgah üçün istifadə olunur. Sənə dərgah qurulanda, gündəlik giriş seriyandan və Telegram Stars ilə alaraq qazanırsan. Coin pul deyil və nağdlaşdırıla bilməz.',
  'faq.gifts.q': 'Hədiyyələr nədir?',
  'faq.gifts.a': 'Coin ilə alıb kiməsə göndərdiyin kiçik əşyalar. Onun profilindəki hədiyyələr bölməsində görünür. Hədiyyə cədvəli qiymətə görə yox, saya görə hesablayır: on nəfərdən ucuz hədiyyə, bir nəfərdən bahalı hədiyyəni üstələyir.',
  'faq.ranks.q': 'Cədvəllər necə işləyir?',
  'faq.ranks.a': 'Beş cədvəl: dərgah dəyəri, woof, bəyənmə, hədiyyə və izləyici. Woof, bəyənmə, hədiyyə və izləyici bu gün, bu həftə, bu ay və ya bütün zamanlar üzrə süzülür və yalnız o aralıqda baş verənləri sayır; yəni gündəlik cədvəllər hər gün sıfırlanır. Dərgah dəyərinin dövrü yoxdur, çünki o hadisə sayı deyil, müddəti bitən canlı nüfuzdur.',
  'faq.discover.q': 'Şəbəkə və Qlobal?',
  'faq.discover.a': 'Şəbəkə yaxınlığındakı insanları göstərir və məkanın lazımdır. Qlobal məkanı tamamilə nəzərə almır və hamını göstərir; onlayn və son vaxtlar aktiv olanlar öndədir. Filtrlər hər ikisinə şamil olunur.',
  'faq.location.q': 'Məkan necə işləyir?',
  'faq.location.a': 'Məkanı bot söhbətindən paylaşırsan və yaddaşa yazılmazdan əvvəl təxminən 500 metrlik şəbəkəyə oturdulur, yəni heç kim dəqiq tapıla bilməz. Məsafələr həmişə aralıq kimi göstərilir, heç vaxt dəqiq deyil. Kəşfdə Filtrlərin yanındakı məkan düyməsi ilə istənilən vaxt yenilə.',
  'faq.private.q': 'Şəxsi albom nədir?',
  'faq.private.a': 'Profilindəki kilidli şəkil dəsti. Şəxsi söhbətdə o adama açana qədər heç kim görmür və istənilən vaxt yenidən kilidləyə bilərsən, bu da girişi geri alır. Görünürlüyü “Şəxsi” seçilərək paylaşılan paylaşımların şəkilləri də ora düşür.',
  'faq.stories.q': 'Hekayələr necə işləyir?',
  'faq.stories.a': '24 saat qalır. İrəli getmək üçün sağa, geri qayıtmaq üçün sola toxun; heç nə öz-özünə keçmir. Hekayəni kimin izlədiyini görə bilərsən və hekayəyə gələn cavab şəxsi söhbətinə hekayə cavabı kimi işarələnmiş şəkildə düşür.',
  'faq.verify.q': 'Mavi işarə nə deməkdir?',
  'faq.verify.a': 'Şəxsin istədiyimiz pozaya uyğun şəkil göndərdiyi və bunu bir insanın təsdiqlədiyi deməkdir. Hesabın real adama aid olduğunu bildirir, vacib olduğunu yox.',
  'faq.ghost.q': 'Kabus rejimi nədir?',
  'faq.ghost.a': 'Səni Kəşfdən gizlədir, beləcə heç kim gəzərək sənə çata bilmir. Paylaşımların, profilin və cədvəldəki yerin dəyişmir — profilini açmış biri hələ də görə bilər.',
  'faq.block.q': 'Kimisə bloklasam nə olur?',
  'faq.block.a': 'Sənə mesaj yaza bilmir; paylaşımlarını, hekayələrini və profilini görmür, söhbətiniz hər ikiniz üçün yox olur. Ona bildirilmir. Cədvəllərdə görünməyə davam edir, çünki yer qazanılır və bloklamaq kimisə oradan silmək üsulu deyil. Tənzimləmələrdəki Bloklanmış istifadəçilər siyahısında görünür; oradan və ya profilindən bloku aça bilərsən.',
  'faq.report.q': 'Nəyisə şikayət etsəm nə olur?',
  'faq.report.a': 'Yazdığınla birlikdə moderatorlara gedir. Paylaşımı silə və ya hesabı bloklaya bilərlər. Nəticə sənə bildirilmir, lakin lazım olduqda tədbir görülür.',
  'faq.delete.q': 'Hesabımı silsəm nə olur?',
  'faq.delete.a': 'Hər şey gedir: profil, şəkillər, paylaşımlar, şərhlər, mesajlar, coinlər və hədiyyələr bazadan həmişəlik silinir. Geri qaytarıla bilməz və arxa planda heç nə saxlanmır.',
  'support.hint': 'Nə baş verdiyini yaz. Admin bunu istifadəçi adınla birlikdə alır, cavablar bot söhbətinə gəlir.',
  'support.placeholder': 'Nə baş verdi?',
  'support.send': 'Göndər',
  'support.sentTitle': 'Mesaj göndərildi',
  'support.sentBody': 'Admin onu istifadəçi adınla birlikdə aldı. Cavablar bot söhbətinə gəlir.',
  'discover.noLocation': 'Yaxınlıqdakıları görmək üçün məkanını paylaş',
  'discover.noLocation.body': 'Şəbəkə məsafəyə görə sıralanır, ona görə bir dəfə məkan paylaşana qədər boş qalır. Filtrlərin yanındakı 📍 düyməsi ilə istənilən vaxt yeniləyə və ya silə bilərsən.',
