  'ranks.howTitle': 'Bu cədvəl necə işləyir',
  'ranks.how.court': 'Dərgah dəyəri nüfuzundur. Kimsə sənə dərgah qurmaq üçün coin xərcləyəndə qalxır və pulun birbaşa təsir etdiyi yeganə cədvəldir. Dərgah son ödənişdən 30 gün davam edir — bu müddətdə kimsə yenidən qurmasa dəyərin 2-yə düşür və bu cədvəldən çıxırsan.',
