  'album.unlockedNotice': 'te ha abierto su álbum privado',
  'album.unlockedByYou': 'Le has abierto tu álbum privado',
  'discover.noLocation.later': 'Puedes actualizar tu ubicación cuando quieras con el botón 📍 junto a Filtros.',
  'court.howTitle': 'Cómo funciona el cortejo',
  'court.how.what': 'Cortejar es gastar monedas para subir el estatus de alguien. Tu nombre aparece en su perfil como quien le corteja y su valor de corte sube según lo que pagues.',
  'court.how.cost': 'Cada cortejo cuesta el doble de su valor actual, así que el precio sube cada vez. La mitad de lo que pagas va a esa persona como monedas que puede gastar; la otra mitad sale de circulación.',
  'court.how.expiry': 'Un cortejo dura 30 días desde el último pago. Si nadie vuelve a cortejar en ese plazo, el valor baja a 2 y el título desaparece.',
  'court.how.rank': 'El valor de corte es la tabla principal y la única en la que el dinero influye directamente. Quedarse arriba significa ser cortejado otra vez antes de que se acaben los 30 días.',
  'court.thenZero': 'luego baja a 2',
  'court.lapsed': 'Tu valor de corte se está agotando. Un nuevo cortejo lo reinicia a 30 días.',
  'settings.faq': 'Cómo funciona RIDE',
  'faq.intro': 'Todo en palabras claras: qué hace cada cosa y qué cambia realmente el resultado.',
  'faq.what.q': '¿Qué es RIDE?',
  'faq.what.a': 'Una app social que funciona dentro de Telegram. Tienes perfil, feed, historias y chat privado, además de formas de mostrar interés: woofs, regalos y cortejo. Descubrir encuentra gente cerca de ti o en cualquier parte del mundo, y las tablas muestran quién está recibiendo más atención ahora mismo.',
  'faq.username.q': '¿Nombre de usuario o nombre visible?',
  'faq.username.a': 'Tu nombre de usuario es como se te nombra en todas partes — comentarios, chats, avisos y tablas — y es único. El nombre visible es como te llamas, y aparece en tu perfil y en las tarjetas de Descubrir. Ninguno es tu usuario de Telegram.',
  'faq.woof.q': '¿Qué es un woof?',
  'faq.woof.a': 'Un toque gratuito que envías desde el perfil de alguien para decir que te has fijado. Uno por persona, así que la tabla mide cuánta gente distinta ha pasado, no cuántas veces ha vuelto una sola.',
  'faq.court.q': '¿Qué es el cortejo y el valor de corte?',
  'faq.court.a': 'Cortejar es pagar monedas para subir el estatus de alguien. Su valor de corte sube, tu nombre aparece en su perfil y asciende en la tabla. Dura 30 días desde el último cortejo. Si nadie vuelve a cortejar en ese plazo, el valor cae a 2 — el valor inicial — y el título desaparece. Es un estatus que hay que mantener, no algo que se compra una vez.',
  'faq.courtMoney.q': '¿Cuánto cuesta cortejar y quién recibe el dinero?',
  'faq.courtMoney.a': 'Cada cortejo cuesta el doble del valor actual de la persona, así que el precio sube. La mitad de lo que pagas va directamente a ella en monedas que puede gastar. La otra mitad sale de circulación.',
  'faq.coins.q': '¿Para qué sirven las monedas?',
  'faq.coins.a': 'Las monedas pagan regalos y cortejos. Las consigues cuando te cortejan, con tu racha diaria de inicio de sesión y comprándolas con Telegram Stars. No son dinero y no se pueden retirar.',
  'faq.gifts.q': '¿Qué son los regalos?',
  'faq.gifts.a': 'Objetos pequeños que compras con monedas y envías a alguien. Aparecen en la pestaña de regalos de su perfil. La tabla cuenta cuántos regalos ha recibido, no lo que costaron: diez regalos baratos de diez personas superan a uno caro de una sola.',
  'faq.ranks.q': '¿Cómo funcionan las tablas?',
  'faq.ranks.a': 'Cinco tablas: valor de corte, woofs, me gusta, regalos y seguidores. Woofs, me gusta, regalos y seguidores se filtran por hoy, esta semana, este mes o siempre, y sólo cuentan lo ocurrido dentro de esa ventana, así que las tablas diarias se reinician cada día. El valor de corte no tiene periodos, porque es un estatus vivo que caduca, no un recuento de eventos.',
  'faq.discover.q': '¿Cuadrícula y Global?',
  'faq.discover.a': 'La cuadrícula muestra gente cerca de ti y necesita tu ubicación. Global ignora la ubicación por completo y muestra a todo el mundo, primero quienes están en línea o han estado activos hace poco. Los filtros se aplican en ambos.',
  'faq.location.q': '¿Cómo funciona la ubicación?',
  'faq.location.a': 'La compartes desde el chat del bot y se ajusta a una cuadrícula de unos 500 metros antes de guardarse, así que nadie puede ser localizado con precisión. Las distancias siempre se muestran como rangos, nunca exactas. Actualízala cuando quieras con el botón de ubicación junto a Filtros.',
  'faq.private.q': '¿Qué es el álbum privado?',
  'faq.private.a': 'Un conjunto de fotos bloqueado en tu perfil. Nadie las ve hasta que se las desbloqueas a esa persona en el chat privado, y puedes volver a bloquearlo cuando quieras, lo que retira el acceso. Publicar con visibilidad Privada también manda las fotos ahí.',
  'faq.stories.q': '¿Cómo funcionan las historias?',
  'faq.stories.a': 'Duran 24 horas. Toca el lado derecho para avanzar y el izquierdo para retroceder; nada avanza solo. Puedes ver quién ha visto la tuya, y una respuesta a una historia llega a tu chat privado marcada como respuesta a ella.',
  'faq.verify.q': '¿Qué significa la marca azul?',
  'faq.verify.a': 'Que la persona envió una foto con la pose que pedimos y una persona real la aprobó. Significa que la cuenta es de alguien real, no que sea importante.',
  'faq.ghost.q': '¿Qué es el modo fantasma?',
  'faq.ghost.a': 'Te oculta de Descubrir para que nadie pueda llegar a ti navegando. Tus publicaciones, tu perfil y tus posiciones en las tablas no cambian: quien tenga tu perfil abierto sigue viéndolo.',
  'faq.block.q': '¿Qué pasa cuando bloqueo a alguien?',
  'faq.block.a': 'No puede escribirte ni ver tus publicaciones, historias o perfil, y vuestra conversación desaparece para ambos. No se le avisa. Sigue apareciendo en las tablas, porque un puesto se gana y bloquear no es la forma de sacar a alguien de ahí. Aparece en Ajustes, en Usuarios bloqueados, y puedes desbloquearlo ahí o desde su perfil.',
  'faq.report.q': '¿Qué pasa cuando denuncio algo?',
  'faq.report.a': 'Va a los moderadores junto con lo que hayas escrito. Pueden borrar la publicación o vetar la cuenta. No se te informará del resultado, pero se actúa cuando corresponde.',
  'faq.delete.q': '¿Qué pasa si borro mi cuenta?',
  'faq.delete.a': 'Se va todo: perfil, fotos, publicaciones, comentarios, mensajes, monedas y regalos se eliminan de la base de datos para siempre. No se puede deshacer y no se guarda nada en segundo plano.',
  'support.hint': 'Cuenta qué ha pasado. Un administrador lo recibe junto con tu usuario y responde por el chat del bot.',
  'support.placeholder': '¿Qué ha pasado?',
