  'ranks.howTitle': 'So funktioniert diese Rangliste',
  'ranks.how.court': 'Der Court-Wert ist dein Rang. Er steigt, wenn jemand Coins ausgibt, um dich zu umwerben, und ist die einzige Rangliste, auf die Geld direkt wirkt. Ein Umwerben gilt 30 Tage ab der letzten Zahlung: wirbt niemand erneut, fällt dein Wert auf 2 und du fällst aus dieser Rangliste.',
