  'faq.ghost.q': 'O que é o modo fantasma?',
  'faq.ghost.a': 'Ele esconde você do Descobrir, para ninguém chegar até você navegando. Suas publicações, seu perfil e suas posições nas tabelas não mudam — quem estiver com seu perfil aberto continua vendo.',
