  'court.howTitle': 'دربار چگونه کار می‌کند',
  'court.how.what': 'دربار یعنی پرداخت سکه برای بالا بردن جایگاه کسی. نام شما در پروفایل او دیده می‌شود و ارزش دربار او افزایش می‌یابد.',
